server.createContext("/v1/users", exchange ->
    respond(exchange, 200, "{\"id\":1,\"name\":\"Ala Kowalska\"}"));

server.createContext("/v2/users", exchange ->
    respond(exchange, 200, "{\"id\":1,\"firstName\":\"Ala\",\"lastName\":\"Kowalska\"}"));
// OBIE wersje dzialaja ROWNOLEGLE - stary klient (v1) nie musi nic zmieniac

server.createContext("/users", exchange -> {
    String version = exchange.getRequestHeaders().getFirst("X-API-Version");
    if ("2".equals(version)) {
        respond(exchange, 200, "{\"id\":1,\"firstName\":\"Ala\",\"lastName\":\"Kowalska\"}");
    } else {
        respond(exchange, 200, "{\"id\":1,\"name\":\"Ala Kowalska\"}"); // domyslnie v1
    }
});
// Alternatywnie: Accept: application/vnd.javaquest.v2+json (przypomnienie z Lesson07)

// DOBRZE: v1 dziala dalej, ale z jawnym ostrzezeniem o terminie wygasniecia
server.createContext("/v1/users", exchange -> {
    exchange.getResponseHeaders().add("Deprecation", "true");
    exchange.getResponseHeaders().add("Sunset", "Sat, 31 Dec 2026 23:59:59 GMT");
    exchange.getResponseHeaders().add("Link", "<https://docs.example.com/migration-v2>; rel=\"deprecation\"");
    respond(exchange, 200, "{\"id\":1,\"name\":\"Ala Kowalska\"}");
});
